"""Sign in with Workpeg — the client side.

Two ways in, because two kinds of application need this.

**A button**, for a UI built with this SDK::

    from workpeg.ui.widgets.interactive import SignInWithWorkpeg

    SignInWithWorkpeg(client_id="acme", redirect_uri="https://acme.test/cb")

**Or nothing at all**, for an application that starts sign-in from its own
logic — a link in an email, a redirect after a trial expires, a mobile app
handing off to a browser::

    from workpeg.auth import WorkpegAuth

    auth = WorkpegAuth(client_id="acme",
                       client_secret=...,
                       redirect_uri="https://acme.test/cb")

    start = auth.begin()
    # keep start.state and start.code_verifier against the user's session,
    # then send them to start.url
    ...
    # back at the callback:
    identity = auth.complete(code=code, state=state, start=start)
    identity.business_id, identity.subject, identity.email

The second is not a lesser path. Everything the button does, it does by
calling it.

WHAT YOU GET BACK IS A STAFF IDENTITY — a person AND the business they signed
in as. One human who belongs to three businesses can sign in three times and
you will receive three different ``subject`` values sharing one ``email``.
Key your accounts on ``subject``. Keying on email merges identities Workpeg
deliberately keeps apart.
"""

from __future__ import annotations

import base64
import hashlib
import json
import secrets
from dataclasses import dataclass, field
from urllib.parse import urlencode

import requests

DEFAULT_ISSUER = "https://api.workpeg.com"

#: Long enough that a slow network does not strand a sign-in, short enough
#: that a hung identity provider does not hold a request open.
DEFAULT_TIMEOUT = 10


class WorkpegAuthError(Exception):
    """Sign-in did not complete. The message says what to tell the user."""


@dataclass
class SignInStart:
    """What to keep while the person is away at Workpeg.

    ``state`` and ``code_verifier`` MUST be stored against the browser
    session — a cookie, a server-side session, anything that comes back with
    the same person — and never in the URL. They are what proves the callback
    belongs to the sign-in this application started, rather than one an
    attacker started and pasted at your user.
    """

    url: str
    state: str
    code_verifier: str
    nonce: str


@dataclass
class WorkpegIdentity:
    """Who signed in, and which business they signed in as."""

    subject: str
    business_id: str
    business_name: str
    role: str
    email: str = ""
    email_verified: bool = False
    name: str = ""
    claims: dict = field(default_factory=dict)

    @property
    def is_owner(self) -> bool:
        return self.role == "owner"


def _b64url(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode()


class WorkpegAuth:
    """A relying party's half of Sign in with Workpeg."""

    def __init__(
        self,
        *,
        client_id: str,
        redirect_uri: str,
        client_secret: str = "",
        issuer: str = DEFAULT_ISSUER,
        scope: str = "openid profile email",
        timeout: int = DEFAULT_TIMEOUT,
    ):
        self.client_id = client_id
        self.client_secret = client_secret
        self.redirect_uri = redirect_uri
        self.issuer = issuer.rstrip("/")
        self.scope = scope
        self.timeout = timeout
        self._jwks_cache: dict | None = None

    # ------------------------------------------------------------- step one
    def begin(self, *, prompt: str = "") -> SignInStart:
        """Build the URL to send somebody to, and the secrets to keep.

        A fresh ``state``, ``nonce`` and PKCE verifier every time. Reusing
        any of them across sign-ins is what makes a replay possible, so they
        are generated here rather than left to the caller to remember.
        """
        state = secrets.token_urlsafe(32)
        nonce = secrets.token_urlsafe(32)
        code_verifier = secrets.token_urlsafe(64)
        challenge = _b64url(hashlib.sha256(code_verifier.encode()).digest())

        params = {
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "response_type": "code",
            "scope": self.scope,
            "state": state,
            "nonce": nonce,
            "code_challenge": challenge,
            "code_challenge_method": "S256",
        }
        if prompt:
            params["prompt"] = prompt

        url = f"{self.issuer}/v1/sso/authorize?{urlencode(params)}"
        return SignInStart(url=url, state=state, code_verifier=code_verifier,
                           nonce=nonce)

    # ------------------------------------------------------------- step two
    def complete(self, *, code: str, state: str,
                 start: SignInStart) -> WorkpegIdentity:
        """Turn a callback into an identity, or raise.

        Checks ``state`` FIRST and in constant time. It is what ties this
        callback to the sign-in this application started; without it an
        attacker can hand your user a callback for an account the attacker
        controls, and your application would log them into it.
        """
        if not secrets.compare_digest(state or "", start.state):
            raise WorkpegAuthError(
                "The sign-in state did not match. Start again.")
        if not code:
            raise WorkpegAuthError("No authorization code was returned.")

        payload = self._exchange(code, start.code_verifier)
        claims = self.verify_id_token(payload["id_token"], nonce=start.nonce)
        return self._identity(claims)

    def _exchange(self, code: str, code_verifier: str) -> dict:
        body = {
            # REQUIRED by RFC 6749 §4.1.3, and the provider enforces it: a body
            # without it is refused with unsupported_grant_type, so no sign-in
            # could complete. Missing originally because every test here
            # stubbed the token endpoint and asserted on its REPLY without ever
            # checking what had been sent to it — the stub answered a request
            # the real provider rejects.
            "grant_type": "authorization_code",
            "code": code,
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "code_verifier": code_verifier,
        }
        if self.client_secret:
            body["client_secret"] = self.client_secret

        response = requests.post(
            f"{self.issuer}/v1/sso/token", json=body, timeout=self.timeout)

        if response.status_code != 200:
            raise WorkpegAuthError(_describe(response))

        try:
            payload = response.json()
        except ValueError as exc:
            raise WorkpegAuthError(
                "The token endpoint did not return JSON.") from exc

        if "id_token" not in payload:
            raise WorkpegAuthError("The token response carried no id_token.")
        return payload

    # ----------------------------------------------------------- validation
    def verify_id_token(self, id_token: str, *, nonce: str = "") -> dict:
        """Verify a token's signature and every claim that binds it here.

        Signature, issuer, audience and expiry — and the nonce, which is
        what stops an id_token captured from one sign-in being replayed
        into another.
        """
        try:
            import jwt
        except ImportError as exc:  # pragma: no cover - dependency guidance
            raise WorkpegAuthError(
                "Verifying an id_token needs PyJWT with its crypto extra: "
                "pip install 'pyjwt[crypto]'") from exc

        header = jwt.get_unverified_header(id_token)
        key = self._signing_key(header.get("kid"))

        try:
            claims = jwt.decode(
                id_token,
                key,
                algorithms=["RS256"],
                audience=self.client_id,
                issuer=self.issuer,
            )
        except Exception as exc:
            raise WorkpegAuthError(f"The id_token did not verify: {exc}")

        if nonce and not secrets.compare_digest(
                str(claims.get("nonce", "")), nonce):
            raise WorkpegAuthError("The id_token nonce did not match.")
        return claims

    def _signing_key(self, kid: str | None):
        import jwt

        for allow_cache in (True, False):
            jwks = self._jwks(use_cache=allow_cache)
            for entry in jwks.get("keys", []):
                if kid is None or entry.get("kid") == kid:
                    return jwt.PyJWK(entry).key
            # A kid we have not seen is the ordinary shape of a key
            # rotation, so refetch ONCE before giving up. Caching without
            # this turns every rotation into an outage.
        raise WorkpegAuthError(
            "The id_token was signed with a key that is not published.")

    def _jwks(self, *, use_cache: bool = True) -> dict:
        if use_cache and self._jwks_cache is not None:
            return self._jwks_cache
        response = requests.get(
            f"{self.issuer}/v1/sso/jwks", timeout=self.timeout)
        if response.status_code != 200:
            raise WorkpegAuthError("Could not fetch Workpeg's signing keys.")
        self._jwks_cache = response.json()
        return self._jwks_cache

    # -------------------------------------------------------------- mapping
    @staticmethod
    def _identity(claims: dict) -> WorkpegIdentity:
        return WorkpegIdentity(
            subject=claims["sub"],
            business_id=claims.get("workpeg_business_id", ""),
            business_name=claims.get("workpeg_business_name", ""),
            role=claims.get("workpeg_role", ""),
            email=claims.get("email", ""),
            email_verified=bool(claims.get("email_verified", False)),
            name=claims.get("name", ""),
            claims=claims,
        )


def _describe(response) -> str:
    """A message an integrator can act on, from an OAuth error response."""
    try:
        body = response.json()
    except ValueError:
        return f"Workpeg refused the sign-in (HTTP {response.status_code})."

    error = body.get("error", "")
    description = body.get("error_description", "")
    hint = {
        "invalid_client": "Check client_id and client_secret.",
        "invalid_grant": (
            "The code was already used, expired, or does not match this "
            "redirect_uri or code_verifier."),
        "invalid_scope": "This client is not allowed one of those scopes.",
    }.get(error, "")
    return " ".join(part for part in (description, hint) if part) or json.dumps(
        body)
